      (1, 1431, 4, 'D53336D7', '1740983225', null, '2026-02-09', '2026-02-18 10:17:58', '2026-02-09', 1289, 1289, 'ARRENDAMIENTO DEL APARTAMENTO 307 EN VILLAS ALMORETO', 1011, 4000, 1, 'V', 'JES', null, null, 'JES', '2026-02-18 00:00:00', 'V', null, null, null, 12, 5, 178.57, true, null, 0, null, null, null, null, null, 0, true, null, null, null, 1, 2026, null, 2, 0, 0, 0, null, null, null, null, 'C', true, 10, 2, null, null, 0, 0, 0, 0, 0, 0, 0, 0, 0, null, null, null, null, 'N', 0, null, null),
      (1, 1432, 4, 'F37102AB', '1881164402', null, '2026-02-09', '2026-02-18 10:22:54', '2026-02-09', 1579, 1579, 'SERVICIO DE ARRENDAMIENTO DE LA BODEGA 206', 1011, 17138, 1, 'V', 'JES', null, null, 'JES', '2026-02-18 00:00:00', 'V', null, null, null, 12, 5, 765.09, true, null, 0, null, null, null, null, null, 0, true, null, null, null, 9, 2026, null, 2, 0, 0, 0, null, null, null, null, 'C', true, 10, 2, null, null, 0, 0, 0, 0, 0, 0, 0, 0, 0, null, null, null, null, 'N', 0, null, null)),
  x as (
    insert into public.compras (organizacion_id, localidad_id, numero, tipo_documento, tipo_documento_id, serie, documento, fecha_documento, fecha_ingreso, fecha_vencimiento,
